python3 - <<'PY'
import os,re
for root, dirs, files in os.walk('.'):
    dirs[:] = [d for d in dirs if d not in {'.git','node_modules'}]
    for f in files:
        p=os.path.join(root,f)
        try: s=open(p,encoding='utf-8').read()
        except: continue
        if re.search(r'\bstore\.Memo\b|\bMemo\b',s):
            hits=[(i+1,l) for i,l in enumerate(s.splitlines()) if re.search(r'\bstore\.Memo\b|\bMemo\b',l)]
            print(p, ':', ', '.join(str(i) for i,_ in hits))
            for i,l in hits: print(f'  {i}: {l.strip()}')
PY

